/** @param {import('@deepseek-ai/cordis').Context} ctx */
export function apply(ctx) {
  ctx.effect(() => ctx.slots.inject('settings.section', () => ctx.slots.register({
    name: 'settings.section',
    id: SECTION,
    order: 40,
    label: () => '派活',
  }, () => h(DelegateSection))), 'delegate: settings section')
}

function DelegateSection() {
  const [state, setState] = useState({ status: 'loading' })

  useEffect(() => {
    let gone = false
    fetch(PATH, { headers: { accept: 'application/json' } })
      .then(async (response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`)
        return response.json()
      })
      .then((value) => { if (!gone) setState({ status: 'ready', value }) })
      .catch((error) => { if (!gone) setState({ status: 'error', message: error instanceof Error ? error.message : '读取失败。' }) })
    return () => { gone = true }
  }, [])

  if (state.status === 'loading') {
    return h('div', { style: styles.section }, h('div', { style: styles.mutedCard }, '配置加载中…'))
  }
  if (state.status === 'error') {
    return h('div', { style: styles.section },
      h('div', { style: { ...styles.mutedCard, color: 'var(--dsw-alias-state-error-primary)' } }, `读不到派活的配置：${state.message}`),
    )
  }
  return h(Editor, { value: state.value })
}

/** @param {{ value: { directories?: unknown, idleDays?: unknown, skipScheduled?: unknown, keepTools?: unknown } }} props */
function Editor({ value }) {
  const saved = Array.isArray(value.directories) ? value.directories.filter(item => typeof item === 'string') : []
  const savedDays = typeof value.idleDays === 'number' ? value.idleDays : 14
  const savedSkip = typeof value.skipScheduled === 'boolean' ? value.skipScheduled : true
  const savedKeep = Array.isArray(value.keepTools) ? value.keepTools.filter(item => typeof item === 'string') : []
  const [dirs, setDirs] = useState(saved)
  const [days, setDays] = useState(String(savedDays))
  const [skip, setSkip] = useState(savedSkip)
  const [extraTools, setExtraTools] = useState(savedKeep)
  const [search, setSearch] = useState('')
  const [searchFocus, setSearchFocus] = useState(false)
  const searchInputRef = useRef(null)
  const [overrides, setOverrides] = useState({})
  const [allTools, setAllTools] = useState({ status: 'loading', list: [] })
  const [toolsError, setToolsError] = useState('')
  const [lastLoadedAt, setLastLoadedAt] = useState(0)
  const [refreshing, setRefreshing] = useState(false)
  const loadSeq = useRef(0)
  const lastLoadedRef = useRef(0)
  const [note, setNote] = useState({ text: '', ok: false })
  const [busy, setBusy] = useState(false)

  /**
   * 拉取工具清单。宿主没有面向浏览器的事件订阅通道，这里通过 `/delegate/tools/events`
   * 的 SSE 接收 `tools/change`；拿不到推送时由「打开 / 手动刷新 / 窗口聚焦」三条时机兜底。
   * 失败时保留上一次的列表，只额外显示一行错误提示，不清空。
   * @param {{ silent?: boolean }} [options]
   */
  async function loadTools(options = {}) {
    const seq = ++loadSeq.current
    if (!options.silent) setRefreshing(true)
    try {
      const response = await fetch(TOOLS_PATH, { headers: { accept: 'application/json' } })
      if (!response.ok) throw new Error(`HTTP ${response.status}`)
      const body = await response.json()
      if (seq !== loadSeq.current) return
      const list = Array.isArray(body.tools)
        ? body.tools
            .filter(tool => tool && typeof tool.name === 'string')
            .map(tool => ({ name: tool.name, description: typeof tool.description === 'string' ? tool.description : '' }))
        : []
      setAllTools({ status: 'ready', list })
      setToolsError('')
      lastLoadedRef.current = Date.now()
      setLastLoadedAt(lastLoadedRef.current)
    } catch (error) {
      if (seq !== loadSeq.current) return
      const message = error instanceof Error ? error.message : '读取失败。'
      setToolsError(message)
      setAllTools(prev => prev.list.length > 0 ? { status: 'ready', list: prev.list } : { status: 'error', list: [] })
    } finally {
      if (seq === loadSeq.current) setRefreshing(false)
    }
  }

  useEffect(() => {
    void loadTools()
    // 窗口重新聚焦 / 标签页重新可见时，若距上次拉取超过 30 秒就静默重取。
    const refreshIfStale = () => {
      if (Date.now() - lastLoadedRef.current > TOOLS_STALE_MS) void loadTools({ silent: true })
    }
    const onVisibility = () => {
      if (document.visibilityState === 'visible') refreshIfStale()
    }
    document.addEventListener('visibilitychange', onVisibility)
    window.addEventListener('focus', refreshIfStale)
    // 宿主 `tools/change` 经 SSE 推送；收不到（浏览器不支持/连接失败）就靠上面的时机兜底。
    let source
    try {
      source = new EventSource(TOOLS_EVENTS_PATH)
      source.addEventListener('tools/change', () => { void loadTools({ silent: true }) })
    } catch {
      source = undefined
    }
    return () => {
      document.removeEventListener('visibilitychange', onVisibility)
      window.removeEventListener('focus', refreshIfStale)
      if (source) source.close()
    }
  }, [])

  function updateDir(index, nextValue) {
    setDirs(prev => prev.map((item, i) => (i === index ? nextValue : item)))
    if (note.text) setNote({ text: '', ok: false })
  }

  function removeDir(index) {
    setDirs(prev => prev.filter((_, i) => i !== index))
    if (note.text) setNote({ text: '', ok: false })
  }

  function addDir() {
    setDirs(prev => [...prev, ''])
    if (note.text) setNote({ text: '', ok: false })
  }

  function toggleTool(name, checked) {
    setExtraTools(prev => (checked
      ? (prev.includes(name) ? prev : [...prev, name])
      : prev.filter(item => item !== name)))
    if (note.text) setNote({ text: '', ok: false })
  }

  async function save() {
    const directories = dirs.map(line => line.trim()).filter(line => line.length > 0)
    const keepTools = extraTools.map(name => name.trim()).filter(name => name.length > 0)
    const idleDays = Number(days)
    if (!Number.isInteger(idleDays) || idleDays < 1) {
      setNote({ text: '闲置天数要是大于等于 1 的整数。', ok: false })
      return
    }
    setBusy(true)
    try {
      const response = await fetch(PATH, {
        method: 'POST',
        headers: { 'content-type': 'application/json', accept: 'application/json' },
        body: JSON.stringify({ directories, idleDays, skipScheduled: skip, keepTools }),
      })
      const body = await response.json().catch(() => ({}))
      if (response.ok) {
        setDirs(directories)
        setExtraTools(keepTools)
        setNote({ text: '已保存。', ok: true })
      } else {
        setNote({ text: typeof body.error === 'string' ? body.error : '没保存成，刷新后再试。', ok: false })
      }
    } catch {
      setNote({ text: '没保存成，刷新后再试。', ok: false })
    } finally {
      setBusy(false)
    }
  }

  const baseSet = new Set(BASE_KEPT_TOOLS)
  const extraSet = new Set(extraTools)
  const described = new Map(allTools.list.map(tool => [tool.name, tool.description]))
  // 固定组：7 个基础工具永远排最前、已勾选禁用。
  const fixedGroup = {
    key: '__fixed__',
    title: '固定保留',
    fixed: true,
    members: BASE_KEPT_TOOLS.map(name => ({ name, short: name, description: described.get(name) ?? '', fixed: true })),
  }
  // 其余按名字前缀分组，组内按短名排序；组间按成员数降序、同数按组名。
  const byGroup = new Map()
  for (const tool of allTools.list) {
    if (baseSet.has(tool.name)) continue
    const { group, short } = groupOf(tool.name)
    if (!byGroup.has(group)) byGroup.set(group, [])
    byGroup.get(group).push({ name: tool.name, short, description: tool.description, fixed: false })
  }
  const prefixGroups = [...byGroup.entries()]
    .map(([title, members]) => ({
      key: title,
      title,
      fixed: false,
      members: members.sort((a, b) => a.short.localeCompare(b.short) || a.name.localeCompare(b.name)),
    }))
    .sort((a, b) => b.members.length - a.members.length || a.title.localeCompare(b.title))
  const keptGroups = []
  const mergedMembers = []
  for (const group of prefixGroups) {
    const hasCheckedTool = group.members.some(member => extraSet.has(member.name))
    if (group.members.length === 1 && !hasCheckedTool) {
      mergedMembers.push({ ...group.members[0], display: group.members[0].name })
    } else {
      keptGroups.push(group)
    }
  }
  const groups = [fixedGroup, ...keptGroups]
  if (mergedMembers.length > 0) {
    mergedMembers.sort((a, b) => a.name.localeCompare(b.name))
    groups.push({ key: '__other__', title: '其他', fixed: false, members: mergedMembers })
  }

  const query = search.trim().toLowerCase()
  const shown = groups
    .map(group => {
      if (query.length === 0) return { group, members: group.members }
      const members = group.members.filter(member => member.name.toLowerCase().includes(query) || member.short.toLowerCase().includes(query))
      return { group, members }
    })
    .filter(item => item.members.length > 0)

  const isOpen = (group, members) => {
    const defaultOpen = group.fixed || members.some(member => member.fixed || extraSet.has(member.name))
    if (query.length > 0) return true
    return group.key in overrides ? overrides[group.key] : defaultOpen
  }
  const toggleGroup = (group, defaultOpen) => {
    if (query.length > 0) return
    setOverrides(prev => ({ ...prev, [group.key]: !(group.key in prev ? prev[group.key] : defaultOpen) }))
  }

  return h('div', { style: styles.section },
    h('style', null, '.dsh-delegate-search-input::placeholder{color:var(--dsw-alias-label-tertiary);opacity:1;}'),
    h('div', { style: styles.header },
      h('h2', { style: styles.title }, '派活'),
      h('p', { style: styles.subtitle }, '在命中的工作目录中，仅保留派活相关工具并自动清理闲置子会话。'),
    ),
    h('div', { style: styles.card },
      h('div', { style: styles.row },
        h('div', { style: styles.rowText },
          h('span', { style: styles.label }, '工作目录'),
          h('p', { style: styles.description }, '会话目录等于其中一项或在其子目录下时生效；留空表示全部关闭。'),
        ),
        dirs.length === 0
          ? h('p', { style: styles.emptyHint }, '暂无工作目录（当前为全部关闭）')
          : h('div', { style: styles.dirList },
              ...dirs.map((dir, index) =>
                h('div', { key: index, style: styles.dirRow },
                  h('input', {
                    type: 'text',
                    value: dir,
                    placeholder: '/path/to/workspace',
                    disabled: busy,
                    onChange: event => updateDir(index, event.target.value),
                    style: styles.input,
                  }),
                  h('button', {
                    type: 'button',
                    disabled: busy,
                    onClick: () => removeDir(index),
                    style: { ...styles.ghostBtn, opacity: busy ? 0.5 : 1 },
                  }, '移除'),
                ),
              ),
            ),
        h('button', {
          type: 'button',
          disabled: busy,
          onClick: addDir,
          style: { ...styles.addBtn, opacity: busy ? 0.5 : 1 },
        }, '+ 添加目录'),
      ),
      h('div', { style: styles.rowSplit },
        h('div', { style: styles.rowText },
          h('span', { style: styles.label }, '闲置天数'),
          h('p', { style: styles.description }, '子会话超过这么多天未被主会话发过消息，就从列表中移除。'),
        ),
        h('div', { style: styles.daysWrap },
          h('input', {
            type: 'number',
            min: 1,
            step: 1,
            value: days,
            disabled: busy,
            onChange: event => {
              setDays(event.target.value)
              if (note.text) setNote({ text: '', ok: false })
            },
            style: styles.daysInput,
          }),
          h('span', { style: styles.unit }, '天'),
        ),
      ),
      h('div', { style: styles.rowSplit },
        h('div', { style: styles.rowText },
          h('span', { style: styles.label }, '定时任务不接管'),
          h('p', { style: styles.description }, '开启后，定时任务投递到的会话照常使用全部工具；关闭则与普通会话一样只能派活。'),
        ),
        h('button', {
          type: 'button',
          role: 'switch',
          'aria-checked': skip,
          'aria-label': '定时任务不接管',
          disabled: busy,
          onClick: () => {
            setSkip(prev => !prev)
            if (note.text) setNote({ text: '', ok: false })
          },
          style: {
            ...styles.switchTrack,
            cursor: busy ? 'not-allowed' : 'pointer',
            opacity: busy ? 0.5 : 1,
            background: skip ? 'var(--dsw-alias-state-business-primary)' : 'var(--dsw-alias-border-l3)',
          },
        },
          h('span', { style: { ...styles.switchKnob, left: skip ? 20 : 2 } }),
        ),
      ),
      h('div', { style: styles.rowTop },
        h('div', { style: styles.rowText },
          h('span', { style: styles.label }, '额外保留的工具'),
          h('p', { style: styles.description }, '固定保留的 7 个工具已勾选并锁定；下面勾选其它工具即可加入 keepTools，取消即移除。'),
        ),
        h('div', { style: styles.toolsMeta },
          h('p', { style: styles.summary }, `共 ${allTools.list.length} 个工具，${groups.length} 个组，已额外保留 ${extraTools.length} 个。`),
          h('div', { style: styles.toolsMetaRight },
            h('span', { style: styles.refreshTime }, lastLoadedAt ? `上次刷新 ${formatClock(lastLoadedAt)}` : ''),
            h('button', {
              type: 'button',
              disabled: refreshing,
              onClick: () => { void loadTools() },
              style: refreshing ? { ...styles.refreshBtn, opacity: 0.6 } : styles.refreshBtn,
            }, refreshing ? '刷新中…' : '刷新'),
          ),
        ),
        h('p', { style: styles.emptyHint }, '列表随实际可用工具自动更新：进入页面、点「刷新」或窗口重新聚焦时会重新拉取。延迟加载的 MCP 工具要等对应服务首次连上后才会出现，没看到就稍后点「刷新」。'),
        h('div', { style: styles.searchWrap },
          h('span', { style: styles.searchIcon, 'aria-hidden': 'true' },
            h('svg', { width: 15, height: 15, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' },
              h('circle', { cx: 11, cy: 11, r: 7 }),
              h('line', { x1: 21, y1: 21, x2: 16.65, y2: 16.65 }),
            ),
          ),
          h('input', {
            type: 'text',
            className: 'dsh-delegate-search-input',
            value: search,
            placeholder: '按名字搜索工具',
            disabled: busy,
            ref: searchInputRef,
            onChange: event => setSearch(event.target.value),
            onFocus: () => setSearchFocus(true),
            onBlur: () => setSearchFocus(false),
            style: {
              ...styles.searchInput,
              borderColor: searchFocus ? 'var(--dsw-alias-state-business-primary)' : 'var(--dsw-alias-border-l3)',
              paddingRight: search.length > 0 ? 32 : 10,
            },
          }),
          search.length > 0
            ? h('button', {
                type: 'button',
                'aria-label': '清除搜索',
                onClick: () => {
                  setSearch('')
                  if (searchInputRef.current && typeof searchInputRef.current.focus === 'function') searchInputRef.current.focus()
                },
                style: styles.searchClear,
              }, h('svg', { width: 14, height: 14, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round' },
                h('line', { x1: 6, y1: 6, x2: 18, y2: 18 }),
                h('line', { x1: 18, y1: 6, x2: 6, y2: 18 }),
              ))
            : null,
        ),
        toolsError
          ? h('p', { style: { ...styles.emptyHint, color: 'var(--dsw-alias-state-error-primary)' } }, `刷新失败：${toolsError}${allTools.list.length > 0 ? '（下面显示的是上一次的结果）' : ''}`)
          : null,
        allTools.status === 'error'
          ? h('p', { style: styles.emptyHint }, '工具清单暂时读不到。')
          : allTools.status === 'loading'
            ? h('p', { style: styles.emptyHint }, '工具清单加载中…')
            : shown.length === 0
              ? h('p', { style: styles.emptyHint }, '没有匹配的工具。')
              : h('div', { style: styles.toolList },
                  ...shown.map(({ group, members }, groupIndex) => {
                    const open = isOpen(group, members)
                    const defaultOpen = group.fixed || members.some(member => member.fixed || extraSet.has(member.name))
                    return h('div', { key: group.key, style: { display: 'flex', flexDirection: 'column' } },
                      h('button', {
                        type: 'button',
                        onClick: () => toggleGroup(group, defaultOpen),
                        style: groupIndex === 0 ? { ...styles.groupHeader, borderTop: 'none' } : styles.groupHeader,
                      },
                        h('span', { style: styles.chevron }, open ? '▾' : '▸'),
                        h('span', { style: styles.groupTitle, title: group.title }, group.title),
                        h('span', { style: styles.groupCount }, query.length > 0 ? `匹配 ${members.length} 个` : `${members.length} 个`),
                      ),
                      open
                        ? h('div', { style: { display: 'flex', flexDirection: 'column' } },
                            ...members.map(member =>
                              h('div', { key: member.name, style: styles.toolRowMember },
                                h('input', {
                                  type: 'checkbox',
                                  checked: member.fixed || extraSet.has(member.name),
                                  disabled: busy || member.fixed,
                                  onChange: event => toggleTool(member.name, event.target.checked),
                                  'aria-label': member.name,
                                  style: styles.checkbox,
                                }),
                                h('div', { style: styles.toolRowMain },
                                  h('span', { style: styles.toolName, title: member.name }, member.display ?? member.short),
                                  member.description ? h('p', { style: styles.toolDesc, title: member.description }, member.description) : null,
                                ),
                                member.fixed ? h('span', { style: styles.fixedTag }, '固定保留') : null,
                              ),
                            ),
                          )
                        : null,
                    )
                  }),
                ),
      ),
    ),
    h('div', { style: styles.footer },
      h('p', {
        style: {
          ...styles.statusText,
          color: note.text
            ? (note.ok ? 'var(--dsw-alias-state-success-primary)' : 'var(--dsw-alias-state-error-primary)')
            : 'transparent',
        },
      }, note.text || ' '),
      h('button', {
        type: 'button',
        disabled: busy,
        onClick: () => { void save() },
        style: {
          ...styles.primaryBtn,
          opacity: busy ? 0.5 : 1,
          cursor: busy ? 'not-allowed' : 'pointer',
        },
      }, busy ? '保存中…' : '保存'),
    ),
  )
}
